struct ValueSelector {
    int data = 5;

    // 1. Lvalue Ref-Qualifier (For named objects)
    int get_val() const & {
        return data; // Read-only path
    }

    // 2. Rvalue Ref-Qualifier (For temporaries)
    //    Allows move semantics or modification of the temporary.
    int get_val() && {
        return -data; // Temporary path
    }
};

// Usage:
// ValueSelector obj;
// obj.get_val();        // Calls 'const &'
// ValueSelector{}.get_val(); // Calls '&&'
//
// Ref-qualifiers are part of the function signature.
